# Generated by build.py from recipe.yml for recipe http-upload-several-files-at-once. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/reports', 'site/inbox', 'drop' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'a.txt'), "alpha`n")
[IO.File]::WriteAllText((Join-Path $PWD 'b.txt'), "bravo`n")
[IO.File]::WriteAllText((Join-Path $PWD 'c.txt'), "charlie`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/reports/old.txt'), "from last week`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/inbox/keep.txt'), "keep`n")
[IO.File]::WriteAllText((Join-Path $PWD 'drop/readme.txt'), "uploads land here`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-uploads', '--allow-anonymous', '--list-directories', 'http://127.0.0.1:8080/', 'ws://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -T "{a,b,c}.txt" -w "%{http_code} %{url.path}\n" http://127.0.0.1:8080/reports/ --next ws://127.0.0.1:8081/reports/ } finally { Stop-Process $server0 }
